import sys

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    g = [[int(x) for x in data[2 + i * c: 2 + (i + 1) * c]] for i in range(r)]
    prev = [-1] * c
    for i in range(r):
        cur = [-1] * c
        for j in range(c):
            v = g[i][j]
            if v < 0:
                continue
            if i == 0 and j == 0:
                cur[j] = v
                continue
            best = -1
            if prev[j] > best:
                best = prev[j]
            if j > 0 and cur[j - 1] > best:
                best = cur[j - 1]
            if best >= 0:
                cur[j] = best + v
        prev = cur
    print(prev[c - 1])

main()

